const $ = (sel, root=document) => root.querySelector(sel);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusClass = s => s==='Confirmed'||s==='Resolved'?'green':s==='Missing'?'amber':s==='Invalid'?'red':'amber';
const toast = msg => { const el=$('#toast'); if(!el)return; el.textContent=msg;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),2800); };
async function api(path, options={}) {
  const res=await fetch(`${API}${path}`,options); const type=res.headers.get('content-type')||'';
  if(!res.ok){let body={};try{body=type.includes('json')?await res.json():{message:await res.text()}}catch{};const d=body.detail;throw new Error((typeof d==='string'?d:d?.message)||body.message||'The request could not be completed.');}
  return type.includes('application/pdf')||type.includes('audio/')?res:res.json();
}
async function initSession(){
  try {
    if(!state.sessionId){const made=await api('/sessions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:state.applicationName,use_case:'scholarship',preferred_language:state.language})});state.sessionId=made.session_id;state.applicationId=made.application_id;localStorage.setItem('formpilot.session',state.sessionId);}
    else {try{const s=await api(`/sessions/${state.sessionId}`);state.applicationId=s.application_id||s.id;const reverse=Object.fromEntries(Object.entries(fieldApiIds).map(([ui,apiId])=>[apiId,ui]));for(const [apiId,answer] of Object.entries(s.answers||{})){const uiId=reverse[apiId]||apiId;if(uiId in state.answers)state.answers[uiId]=answer.value||'';}state.documentIds=(s.documents||[]).map(d=>d.document_id);const mainDoc=(s.documents||[]).find(d=>d.kind==='application');state.documentId=mainDoc?.document_id||'';if(mainDoc){state.documentName=mainDoc.filename;state.previewUrl=`${API}/documents/${mainDoc.document_id}/file`;state.files=[{type:mainDoc.mime_type}];}}catch{localStorage.removeItem('formpilot.session');state.sessionId='';const made=await api('/sessions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:state.applicationName,use_case:'scholarship',preferred_language:state.language})});state.sessionId=made.session_id;state.applicationId=made.application_id;localStorage.setItem('formpilot.session',state.sessionId);}}
    state.apiReady=true;
  } catch {state.apiReady=false;}
  render();
}
function shell(content){
  const nav = navItems.map(([id,label,ic],i)=>`<button class="nav-item ${state.screen===id?'active':''}" data-screen="${id}">${icons(ic)}<span>${label}</span>${i>0&&i<4?`<span class="nav-num">0${i}</span>`:''}</button>`).join('');
  const bottom=[['dashboard','Home','grid'],['assistant','Assist','spark'],['review','Review','shield'],['draft','Draft','download']].map(([id,l,ic])=>`<button class="bottom-nav ${state.screen===id?'active':''}" data-screen="${id}">${icons(ic)}<span>${l}</span></button>`).join('');
  return `<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark">${icons('files')}</span><span class="brand-name">Form<span>Pilot</span></span></div><div class="nav-label">Workspace</div><nav class="nav-list" aria-label="Main navigation">${nav}</nav><div class="side-spacer"></div><div class="sidebar-bottom"><div class="nav-label">Your progress</div><div class="help-card"><span class="help-icon">${icons('help')}</span><strong>Need a little help?</strong><p>See how FormPilot guides you through an application.</p><button class="link-button" data-action="how">How it works ${icons('arrow','sm')}</button></div><div class="profile-row"><div class="avatar">RK</div><div class="profile-meta"><strong>Rahul Kumar</strong><span>Scholarship applicant</span><button class="link-button" style="margin-top:4px" data-action="delete-session">Delete workspace</button></div></div></div></aside><main class="main"><header class="topbar"><div class="topbar-left"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">${icons('menu')}</button><div class="breadcrumbs">Workspace <span style="color:#c1c8d4;margin:0 6px">/</span> <strong>${navItems.find(x=>x[0]===state.screen)?.[1]||'Dashboard'}</strong></div></div><div class="top-actions"><span class="secure-label">${icons('shield','sm')} Short-lived session storage</span><label class="sr-only" for="languageGlobal">Language</label><select class="top-select" id="languageGlobal" aria-label="Select language"><option value="hi" ${state.language==='hi'?'selected':''}>हिंदी</option><option value="en" ${state.language==='en'?'selected':''}>English</option></select></div></header><section class="content" id="screenContent">${content}</section></main></div><nav class="mobile-bottom" aria-label="Mobile navigation">${bottom}</nav>`;
}
